import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/index.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

it('reports string, object and undefined rejections with their cause while preserving Error identity', async () => {
  const reasons: unknown[] = ['string boom', {code: 503}, undefined, new Error('existing')];
  const results = [];
  for (const reason of reasons) {
    const errors: Error[] = [];
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const orchestrator = createChatOrchestrator(createMockProvider(), new PromptBuilder({identity: 'Assistant'}), undefined, {
      hooks: {
        afterUserInput: async () => { throw reason; },
        onError: async (_session, error) => { errors.push(error); },
      },
    });
    const outcome = await orchestrator.processMessage(session).then(
      () => ({rejected: false, reason: undefined}),
      (caught: unknown) => ({rejected: true, reason: caught})
    );
    const reported = errors[0];
    results.push({
      calls: errors.length,
      isError: reported instanceof Error,
      readable: Boolean(reported?.message),
      original: reason instanceof Error ? reported === reason : reported?.cause === reason,
      rejected: outcome.rejected && outcome.reason === reason,
    });
  }
  expect(results).toEqual(reasons.map(() => ({calls: 1, isError: true, readable: true, original: true, rejected: true})));
});
EOF
 timeout 300 env NODE_OPTIONS=--experimental-vm-modules node node_modules/jest/bin/jest.js --runInBand --runTestsByPath src/orchestration/rejectionHooks.test.ts"

